//! Starflight — an orbital strike for Horizon.
//!
//! An independent reimplementation of the mechanics described by *The Shooting
//! Star [Demo]* (All Rights Reserved). No upstream code or assets are used.
//!
//! Every hook signature, event field and host method below was read from the
//! mod API generated by `horizon-rust/horizon@69ab572`, which this crate is
//! compiled against — nothing here is guessed.

#![forbid(unsafe_code)]

pub mod core;
pub mod strike;

use std::sync::Mutex;
use mod_api::{
    BlockEdit, BlockRun, Command, CommandArgumentValue, Flow, Hooks, HostSide, Identifier, Item,
    DimensionKey, ItemsEvent, LevelDimension, LogicalSide, RegisterCommandsEvent, RegistrationContext, RightClickItemEvent,
    RunModCommandEvent, ServerHost, ServerTickEvent,
};

/// The id of a vanilla level, or `None` for a data-pack or mod dimension.
///
/// A command hands its level over as a key; only the three vanilla keys are
/// named here, and a custom one is refused rather than silently redirected to
/// the overworld, which would carve the wrong level.
fn level_name_of_key(key: DimensionKey) -> Option<&'static str> {
    match key {
        DimensionKey::OVERWORLD => Some("minecraft:overworld"),
        DimensionKey::NETHER => Some("minecraft:the_nether"),
        DimensionKey::END => Some("minecraft:the_end"),
        _ => None,
    }
}

/// The same, for the click hook, which hands over the dimension itself.
fn level_name(dimension: LevelDimension) -> Option<&'static str> {
    match dimension {
        LevelDimension::Overworld => Some("minecraft:overworld"),
        LevelDimension::Nether => Some("minecraft:the_nether"),
        LevelDimension::End => Some("minecraft:the_end"),
        LevelDimension::Custom(_) => None,
    }
}

/// The item whose right-click calls a strike down.
pub const STRIKE_ITEM: &str = "starflight:orbital_rocket";

/// Radius of the carve, in blocks.
const STRIKE_RADIUS: f64 = 16.0;
/// Blocks carved above the target.
const CARVE_ABOVE: i32 = 24;
/// Blocks carved below the target.
const CARVE_BELOW: i32 = 16;
/// The block every carve writes.
const CARVE_BLOCK: &str = "minecraft:air";
/// `LevelEvent` id for a firework-style burst. Borrowed so the impact reads as
/// an explosion without the mod shipping its own particles.
const IMPACT_EVENT: i32 = 2002;

/// The content this mod declares, kept separate from the hook so it can be
/// checked without a `RegistrationContext` (which only the game can build).
///
/// `orbital_rocket` copies `minecraft:firework_rocket`: a stackable item that
/// places no block, which is what a strike call should be. One strike per
/// right-click, and the item is not consumed since nothing declares a
/// `crafting_remainder` or a use count.
#[must_use]
pub fn declarations() -> Vec<Item> {
    vec![Item::new("orbital_rocket", "minecraft:firework_rocket")]
}

/// The mod.
///
/// The hooks take `&self` and the mod must be `Sync`, so the live strikes sit
/// behind a `Mutex`. A poisoned lock means a previous tick panicked; that is
/// handled by doing nothing rather than propagating a panic into the game.
#[derive(Default)]
pub struct Starflight {
    active: Mutex<Vec<strike::Strike>>,
}

#[mod_api::horizon_mod]
impl Hooks for Starflight {
    /// Registers the rocket item. Without this there is nothing to hold.
    ///
    /// `minecraft:firework_rocket` is the template: it is a stackable item with no
    /// block placement, which is what a strike call should be. Called once at
    /// start on both sides, so the item exists wherever the mod loads.
    fn items(&self, _context: &RegistrationContext, event: &mut ItemsEvent<'_>) {
        event.items.extend(declarations());
    }

    /// `/starflight strike [radius]` — the same strike, without needing the item.
    ///
    /// Exists so the carve can be tested on a server with one command, and so the
    /// mechanic is reachable if the item is lost.
    fn register_commands(&self, _host: &mut dyn ServerHost, event: &mut RegisterCommandsEvent<'_>) {
        event.commands.push(Command::new("starflight strike"));
        // A custom radius is operator-only: it can carve very large volumes.
        event
            .commands
            .push(Command::op("starflight strike <radius>", 2));
    }

    /// Runs `/starflight strike`.
    fn run_mod_command(
        &self,
        _host: &mut dyn ServerHost,
        event: &mut RunModCommandEvent<'_>,
    ) -> Flow {
        let literals = &event.command.literals;
        if literals.first().map(String::as_str) != Some("starflight") {
            return Flow::Continue;
        }
        if literals.get(1).map(String::as_str) != Some("strike") {
            return Flow::Continue;
        }

        // An explicit radius, or the default. Out-of-range is refused by the
        // core, which reports why; nothing is clamped.
        let radius = match event.command.argument("radius") {
            Some(CommandArgumentValue::Number(n)) => *n,
            Some(CommandArgumentValue::Integer(n)) => f64::from(*n),
            _ => STRIKE_RADIUS,
        };

        let [x, y, z] = event.command.position;
        // Round down so the column is centred on the block under the command.
        let Some(dimension) = level_name_of_key(event.command.dimension) else {
            eprintln!("starflight: a strike is only supported in the vanilla levels");
            return Flow::Continue;
        };
        let queued = strike::Strike::new(
            &dimension,
            x.floor() + 0.5,
            z.floor() + 0.5,
            radius,
            y as i32 - CARVE_BELOW,
            y as i32 + CARVE_ABOVE,
        );

        match queued {
            Ok(s) => {
                if let Ok(mut active) = self.active.lock() {
                    active.push(s);
                }
                Flow::Cancel
            }
            Err(reason) => {
                eprintln!("starflight: strike refused: {reason}");
                Flow::Continue
            }
        }
    }

    /// Right-clicking with the rocket item calls a strike onto the aimed block.
    fn right_click_item(&self, host: HostSide<'_>, event: &mut RightClickItemEvent<'_>) -> Flow {
        // A client's copy would act on a world it does not own.
        if event.click.side != LogicalSide::Server {
            return Flow::Continue;
        }
        let HostSide::Server(server) = host else {
            return Flow::Continue;
        };

        // `ItemKey` is opaque, so the id is resolved through the host and compared.
        let Ok(id) = Identifier::parse(STRIKE_ITEM) else {
            return Flow::Continue;
        };
        let Some(wanted) = server.item_key(&id) else {
            return Flow::Continue;
        };
        if event.click.stack.item() != wanted {
            return Flow::Continue;
        }

        let [x, y, z] = event.click.pos;
        let player = event.click.player;
        let hand = event.click.hand;
        let Some(dimension) = level_name(event.click.dimension) else {
            eprintln!("starflight: a strike is only supported in the vanilla levels");
            return Flow::Continue;
        };
        let queued = strike::Strike::new(
            &dimension,
            f64::from(x) + 0.5,
            f64::from(z) + 0.5,
            STRIKE_RADIUS,
            y - CARVE_BELOW,
            y + CARVE_ABOVE,
        );

        match queued {
            Ok(s) => {
                if let Ok(mut active) = self.active.lock() {
                    active.push(s);
                }
                // The rocket is not consumed: this SDK exposes no public write
                // to a player's inventory (ItemPlace is crate-private, and no
                // generated host method sets a player slot). Written up in
                // README "Known gaps" rather than faked.
                let _ = (player, hand);
                Flow::Cancel
            }
            Err(reason) => {
                // Out-of-range input is refused, never quietly clamped (D5).
                eprintln!("starflight: strike refused: {reason}");
                Flow::Continue
            }
        }
    }

    /// Advances every live strike by one tick, writing a budget of blocks.
    fn server_tick(&self, host: &mut dyn ServerHost, _event: &mut ServerTickEvent<'_>) {
        let Ok(mut active) = self.active.lock() else {
            return;
        };
        if active.is_empty() {
            return;
        }

        // One palette for the whole tick: every run writes the same block.
        let Some(air) = host.block_state_id(CARVE_BLOCK) else {
            eprintln!("starflight: {CARVE_BLOCK} is not a known block; dropping strikes");
            active.clear();
            return;
        };

        let mut finished = Vec::new();
        for (index, s) in active.iter_mut().enumerate() {
            let positions = s.tick();
            if positions.is_empty() {
                if s.phase() == strike::Phase::Done {
                    finished.push(index);
                }
                continue;
            }

            let edit = BlockEdit {
                palette: vec![air],
                filters: Vec::new(),
                runs: positions
                    .iter()
                    .map(|p| BlockRun {
                        x: p.x,
                        y: p.y,
                        z: p.z,
                        height: 1,
                        surface: None,
                        block: 0,
                        only: None,
                    })
                    .collect(),
            };

            if let Err(reason) = host.edit_blocks(&s.dimension, &edit) {
                // The edit is all-or-nothing, so a refusal leaves the world
                // untouched; abandon the strike instead of retrying forever.
                eprintln!("starflight: block edit refused: {reason}");
                finished.push(index);
                continue;
            }

            // The final batch is the impact: mark it and drop the strike.
            if s.phase() == strike::Phase::Done {
                if let Some(level) = host.level(&s.dimension) {
                    let y = positions.first().map_or(64, |p| p.y);
                    let x = positions.first().map_or(0, |p| p.x);
                    let z = positions.first().map_or(0, |p| p.z);
                    let _ = level.global_level_event(host, IMPACT_EVENT, [x, y, z], 0);
                }
                finished.push(index);
            }
        }

        for index in finished.into_iter().rev() {
            active.swap_remove(index);
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_rocket_item_is_declared() {
        let items = declarations();
        assert_eq!(items.len(), 1, "exactly one item is declared");

        let rocket = &items[0];
        assert_eq!(rocket.id, "orbital_rocket", "namespaced by the mod id");
        assert_eq!(
            rocket.template, "minecraft:firework_rocket",
            "the template must be a real vanilla item"
        );
        // The template places no block, so neither does the item.
        assert_eq!(rocket.block, None);
        // Nothing consumes it: one rocket can call strikes indefinitely.
        assert_eq!(rocket.crafting_remainder, None);
    }

    #[test]
    fn a_command_strike_carves_a_real_volume() {
        // The same path `/starflight strike` takes, minus the game types: a
        // strike is built, then drained the way the tick loop drains it.
        let mut s =
            strike::Strike::new("minecraft:overworld", 0.5, 0.5, STRIKE_RADIUS, 60, 100)
                .expect("valid");
        let total = s.total();
        assert!(total > 0, "a strike must produce positions");

        let mut delivered = 0usize;
        let mut ticks = 0u32;
        while s.phase() != strike::Phase::Done && ticks < 100_000 {
            delivered += s.tick().len();
            ticks += 1;
        }

        assert_eq!(delivered as u64, total, "every position delivered once");
        assert!(
            ticks >= strike::DESCENT_TICKS,
            "the descent precedes the carve"
        );
    }

    #[test]
    fn the_declared_id_matches_the_id_the_click_hook_matches_on() {
        // If these drift apart, right-clicking would never start a strike and
        // the item would appear to do nothing.
        let rocket = &declarations()[0];
        assert_eq!(
            format!("starflight:{}", rocket.id),
            STRIKE_ITEM,
            "the registered id and the id the hook looks for must agree"
        );
    }
}
